def http_hello_page(request, response):
    # Read the request data
    request_data = request.read().decode('utf-8')

    # Extract the username from the request (assuming it's in the query string)
    # This example assumes the request contains a query parameter 'name'
    # For example: GET /?name=John HTTP/1.1
    start = request_data.find('name=')
    if start != -1:
        start += len('name=')
        end = request_data.find(' ', start)
        if end == -1:
            end = len(request_data)
        username = request_data[start:end]
    else:
        username = "Unknown"

    # Create the response message
    response_message = f"Hello {username}"

    # Write the response to the response stream
    response.write(response_message.encode('utf-8'))
